import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    words = data[1:1 + n]
    a, b = data[1 + n], data[2 + n]
    ia = ib = -1
    best = n
    for i, w in enumerate(words):
        if w == a:
            ia = i
            if ib != -1 and i - ib < best:
                best = i - ib
        elif w == b:
            ib = i
            if ia != -1 and i - ia < best:
                best = i - ia
    print(best)

